from bisect import bisect_left
def min_sub_array_len(target, nums):
    pref = [0]
    for x in nums: pref.append(pref[-1] + x)
    best = len(nums) + 1
    for r in range(1, len(pref)):
        need = pref[r] - target
        k = bisect_left(pref, need, 0, r)
        if k < r and pref[r] - pref[k] >= target:
            best = min(best, r - k)
    return best if best <= len(nums) else 0

