def find_substring(s, words):
    if not s or not words: return []
    L = len(words[0]); m = len(words)
    need = Counter(words); res = []
    starts = [s[i:i+L] for i in range(len(s) - L + 1)]
    for off in range(L):
        have = Counter(); used = 0
        for i in range(off, len(starts), L):
            if i >= off + m:
                old = starts[i - m]
                have[old] -= 1
                if have[old] < need[old]: used -= 1
            w = starts[i]
            have[w] += 1
            if have[w] <= need[w]: used += 1
            if used == len(need):
                res.append((i - m + 1) * L)
    return sorted(set(res))
